import random
import string
from typing import List

# Data type: ASCII/UTF-8 text interpreted as C-string
# Goal: Produce interesting, valid strings that exercise different code paths in stubs using FUZZ_PARAM_STR
# Strategy:
# - Generate a mix of: empty, short, long (bounded), format-like strings, numeric strings, paths, device-like names,
#   known keywords for tsk_* type parsers (image/fs/vs/pool types), UTF-8 with multibyte, and strings with spaces,
#   punctuation, and boundary characters. Always ensure result is valid UTF-8 and does not contain embedded NUL,
#   because the stubs pass .c_str() to printf-style APIs.
# - Keep size <= 4096 bytes.

MAX_SIZE = 4096

KNOWN_IMG_TYPES = [
    "raw", "ewf", "vmdk", "vhd", "aff", "aff4", "qcow", "detect", "logical", "pool"
]
KNOWN_VS_TYPES = [
    "dos", "bsd", "sun", "mac", "gpt", "apfs", "lvm", "detect"
]
KNOWN_FS_TYPES = [
    "ntfs", "fat12", "fat16", "fat32", "exfat", "ext2", "ext3", "ext4", "iso9660",
    "hfs", "hfsx", "apfs", "btrfs", "xfs", "yaffs2", "detect"
]
KNOWN_POOL_TYPES = [
    "apfs", "lvm", "detect"
]

# Some UTF-8 multi-byte snippets to test handling
UNICODE_SNIPPETS = [
    "café",               # Latin-1 supplement
    "日本語",              # CJK
    "🙂",                 # emoji
    "Δοκιμή",             # Greek
    "тест",               # Cyrillic
    "𝛑-𝜶",                # math alphas (surrogates)
]

FORMAT_SNIPPETS = [
    "%s", "%d", "%u", "%p", "%.32s", "%08x", "%#llx", "%zu", "%%", "%.*s"
]

PATH_SNIPPETS = [
    "/", ".", "..", "/root", "/etc/passwd", "/dev/null", "C:/Windows/System32",
    "\\\\.\\PHYSICALDRIVE0", "/Volumes/Macintosh HD", "/mnt/disk1/part.img"
]

WORDS = KNOWN_IMG_TYPES + KNOWN_VS_TYPES + KNOWN_FS_TYPES + KNOWN_POOL_TYPES + [
    "password", "hint", "encrypted", "case-sensitive", "volume", "partition", "journal",
    "snapshot", "unallocated", "metadata", "bitmap", "directory", "extent", "keybag"
]

PUNCT = "-_.,:+@#()[]{}!$^&=~"
SAFE_ASCII = string.ascii_letters + string.digits + PUNCT + " "


def rand_ascii(rnd: random.Random, n: int) -> str:
    return ''.join(rnd.choice(SAFE_ASCII) for _ in range(n))


def make_format_like(rnd: random.Random) -> str:
    # Combine literal with several printf tokens
    parts = ["fuzz "]
    for _ in range(rnd.randint(1, 4)):
        parts.append(rnd.choice(FORMAT_SNIPPETS))
        parts.append(" ")
    parts.append(rand_ascii(rnd, rnd.randint(0, 12)))
    return ''.join(parts).strip()


def make_keyword_line(rnd: random.Random) -> str:
    # Produce lines like: "fs=ntfs img=ewf vs=gpt pool=apfs"
    items = []
    if rnd.random() < 0.9:
        items.append(f"img={rnd.choice(KNOWN_IMG_TYPES)}")
    if rnd.random() < 0.9:
        items.append(f"fs={rnd.choice(KNOWN_FS_TYPES)}")
    if rnd.random() < 0.7:
        items.append(f"vs={rnd.choice(KNOWN_VS_TYPES)}")
    if rnd.random() < 0.5:
        items.append(f"pool={rnd.choice(KNOWN_POOL_TYPES)}")
    if rnd.random() < 0.5:
        items.append(f"pass={rand_ascii(rnd, rnd.randint(0, 12))}")
    return ' '.join(items)


def make_unicode_mix(rnd: random.Random) -> str:
    base = rand_ascii(rnd, rnd.randint(0, 20))
    uni = rnd.choice(UNICODE_SNIPPETS)
    tail = rand_ascii(rnd, rnd.randint(0, 20))
    return base + uni + tail


def make_pathy(rnd: random.Random) -> str:
    base = rnd.choice(PATH_SNIPPETS)
    if rnd.random() < 0.6:
        # append a filename-like suffix
        suffix = rand_ascii(rnd, rnd.randint(3, 12)).replace(' ', '_')
        if not suffix:
            suffix = "file"
        if not base.endswith(('/', '\\')):
            base += '/'
        base += suffix
        if rnd.random() < 0.5:
            base += rnd.choice([".img", ".E01", ".vhd", ".vmdk", ".aff", ".dd"])
    return base


def make_numbers(rnd: random.Random) -> str:
    # integer or hex forms, maybe combined
    parts: List[str] = []
    for _ in range(rnd.randint(1, 4)):
        if rnd.random() < 0.5:
            parts.append(str(rnd.randint(0, 2**32 - 1)))
        else:
            parts.append(hex(rnd.getrandbits(64)))
    return ' '.join(parts)


def make_long_text(rnd: random.Random, target_len: int) -> str:
    # Compose from words and ascii, without NULs, keep within target_len
    chunks: List[str] = []
    while sum(len(c) for c in chunks) < target_len:
        choice = rnd.random()
        if choice < 0.3:
            chunks.append(rnd.choice(WORDS))
        elif choice < 0.6:
            chunks.append(rand_ascii(rnd, rnd.randint(1, 12)))
        else:
            chunks.append(rnd.choice(UNICODE_SNIPPETS))
        chunks.append(' ')
    s = ''.join(chunks).strip()
    return s[:target_len]


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    # Choose a pattern family
    kind = rnd.randint(0,  nine := 9)
    if kind == 0:
        s = ""  # empty string
    elif kind == 1:
        s = rand_ascii(rnd, rnd.randint(1, 32))
    elif kind == 2:
        s = make_format_like(rnd)
    elif kind == 3:
        s = make_keyword_line(rnd)
    elif kind == 4:
        s = make_unicode_mix(rnd)
    elif kind == 5:
        s = make_pathy(rnd)
    elif kind == 6:
        s = make_numbers(rnd)
    elif kind == 7:
        # Known tokens only or joined
        tokens = [rnd.choice(KNOWN_IMG_TYPES), rnd.choice(KNOWN_VS_TYPES), rnd.choice(KNOWN_FS_TYPES)]
        s = ' '.join(tokens)
    else:
        # Long but bounded text, sometimes large
        target = rnd.randint(64, min(1024, MAX_SIZE - 1))
        s = make_long_text(rnd, target)

    # Occasionally prepend or append format/control-like wrappers that are still safe
    if s and rnd.random() < 0.3:
        s = f"[{s}]"
    if s and rnd.random() < 0.2:
        s = f"fuzz n=%d msg={s}"

    # Ensure UTF-8 encodable and size bound; avoid embedded NULs (we never add '\0')
    b = s.encode('utf-8', errors='ignore')
    if len(b) >= MAX_SIZE:
        b = b[:MAX_SIZE - 1]
    return b
